import os, ast, json
from collections import defaultdict, deque

inputs_dir='/inputs'
out_path='/work/layout.json'

# Read inert reference text as requested
with open(os.path.join(inputs_dir,'smell-catalog.md'),'r',encoding='utf-8') as f:
    _ref_text=f.read()

# Collect included top-level Python source files
all_names=sorted(os.listdir(inputs_dir))
py_files=[]
for name in all_names:
    if not name.endswith('.py'):
        continue
    if name=='__init__.py':
        continue
    if name.startswith('test_'):
        continue
    if name.endswith('_test.py'):
        continue
    full=os.path.join(inputs_dir,name)
    if os.path.isfile(full):
        py_files.append(name)

py_files=sorted(py_files)
stems={name[:-3] for name in py_files}

# Line counts using splitlines semantics
line_counts={}
texts={}
for name in py_files:
    full=os.path.join(inputs_dir,name)
    with open(full,'r',encoding='utf-8') as f:
        text=f.read()
    texts[name]=text
    line_counts[name]=len(text.splitlines())

PACKAGE='skillc.frontend'

def first_after_package(mod: str):
    if mod==PACKAGE:
        return None
    prefix=PACKAGE + '.'
    if mod.startswith(prefix):
        rest=mod[len(prefix):]
        if not rest:
            return None
        return rest.split('.')[0]
    return None

# Build import graph (edges among siblings only)
adj={name:set() for name in py_files}

for name in py_files:
    text=texts[name]
    try:
        tree=ast.parse(text, filename=name)
    except SyntaxError:
        # If syntax error, skip import extraction but keep file entry
        continue
    self_stem=name[:-3]
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                mod=alias.name
                target=first_after_package(mod)
                if target and target in stems and target!=self_stem:
                    adj[name].add(target + '.py')
        elif isinstance(node, ast.ImportFrom):
            target_stems=[]
            if node.level==1:
                if node.module:
                    # from .module import x
                    target=node.module.split('.')[0]
                    if target:
                        target_stems.append(target)
                else:
                    # from . import module
                    for alias in node.names:
                        nm=alias.name
                        if nm=='*':
                            continue
                        first=nm.split('.')[0]
                        if first:
                            target_stems.append(first)
            elif node.level==0:
                mod=node.module
                if mod:
                    if mod==PACKAGE:
                        # from skillc.frontend import module
                        for alias in node.names:
                            nm=alias.name
                            if nm=='*':
                                continue
                            first=nm.split('.')[0]
                            if first:
                                target_stems.append(first)
                    else:
                        target=first_after_package(mod)
                        if target:
                            target_stems.append(target)
            else:
                # ignore relative imports above level one
                pass

            for st in target_stems:
                if st in stems and st!=self_stem:
                    adj[name].add(st + '.py')

# files rows
files_rows=[]
for name in py_files:
    files_rows.append({
        'name': name,
        'lines': int(line_counts[name]),
        'imports': sorted(adj[name]),
    })

# prefix clusters
stem_list=sorted(stems)
prefix_to_members={}
for stem in stem_list:
    for l in range(4, len(stem)+1):
        pref=stem[:l]
        members=tuple(sorted([s for s in stem_list if s.startswith(pref)]))
        if len(members)>=3:
            prefix_to_members[pref]=members

members_to_prefixes=defaultdict(list)
for pref,members in prefix_to_members.items():
    members_to_prefixes[members].append(pref)

def lcp(strings):
    if not strings:
        return ''
    s1=min(strings)
    s2=max(strings)
    i=0
    m=min(len(s1),len(s2))
    while i<m and s1[i]==s2[i]:
        i+=1
    return s1[:i]

prefix_cluster_rows=[]
for members,prefs in members_to_prefixes.items():
    lp=lcp(list(members))
    files=sorted([m + '.py' for m in members])
    lines=sum(line_counts[f] for f in files)
    prefix_cluster_rows.append({
        'prefix': lp,
        'files': files,
        'lines': int(lines),
    })
prefix_cluster_rows=sorted(prefix_cluster_rows, key=lambda r: r['prefix'])

# import tree clusters
import_tree_rows=[]
for root in py_files:
    direct=adj[root]
    if len(direct) < 3:
        continue
    reached=set([root])
    dq=deque([root])
    while dq:
        cur=dq.popleft()
        for nxt in adj[cur]:
            if nxt not in reached:
                reached.add(nxt)
                dq.append(nxt)
    if len(reached) >= 5:
        files=sorted(reached)
        lines=sum(line_counts[f] for f in files)
        import_tree_rows.append({
            'root': root,
            'files': files,
            'lines': int(lines),
        })
import_tree_rows=sorted(import_tree_rows, key=lambda r: r['root'])

obj={
    'files': files_rows,
    'prefix_clusters': prefix_cluster_rows,
    'import_tree_clusters': import_tree_rows,
}

with open(out_path,'w',encoding='utf-8',newline='') as f:
    json.dump(obj,f,ensure_ascii=False,indent=2)
    f.write('\n')

print('wrote', out_path)
print('files', len(files_rows), 'prefix_clusters', len(prefix_cluster_rows), 'import_tree_clusters', len(import_tree_rows))

